import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { resolve } from "node:path";

export async function launchSql() {
  const base = await readFile(new URL("../supabase/treasury-core.sql", import.meta.url), "utf8");
  const reinvestment = await readFile(new URL("../supabase/pack-reinvestment.sql", import.meta.url), "utf8");
  const ponsHourly = await readFile(new URL("../supabase/pons-v2-hourly.sql", import.meta.url), "utf8");
  return [
    "-- StonkRips: ONE paste into the intended Supabase project's SQL Editor.",
    "-- Generated by npm run launch:sql. Additive: never resets or seeds data.",
    "-- Does not enable automation, packs, swaps, or payouts. Safe to rerun.",
    "begin;",
    base,
    reinvestment.replace(/^begin;\s*$/m, "").replace(/^commit;\s*$/m, ""),
    ponsHourly,
    "commit;",
    "",
  ].join("\n");
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  await writeFile(new URL("../supabase/launch-setup.sql", import.meta.url), await launchSql());
  console.log("Prepared supabase/launch-setup.sql. No database was changed.");
}
